const CORE=[{"id": "prepitch", "title": "투구 전 5초", "body": "OUT → RUNNER → SCORE → BATTER → PLAY", "detail": "공이 오기 전에 현재 상황을 읽고, 내게 공이 왔을 때의 첫 선택과 공이 오지 않았을 때의 역할을 미리 생각한다."}, {"id": "sureout", "title": "확실한 아웃", "body": "잡고 싶은 주자와 잡을 수 있는 주자를 구분한다.", "detail": "공격적인 플레이는 준비된 조건에서 한다. 첫 아웃까지 잃으면서 낮은 확률의 두 아웃을 노리지 않는다."}, {"id": "onebase", "title": "한 베이스 막기", "body": "아웃을 못 잡아도 다음 베이스는 막을 수 있다.", "detail": "이미 안전한 선행주자에게 무리하게 던져 타자주자까지 진루시키지 않는다."}, {"id": "notmyball", "title": "내 공이 아니면 내 역할이 시작된다", "body": "COVER · CUT · BACKUP · BASE · NEXT", "detail": "공이 반대편으로 가는 순간 플레이에서 빠지는 것이 아니라 비어 있는 곳과 다음 송구를 찾는다."}, {"id": "contact", "title": "CONTACT RESET", "body": "RUNNER → CONTACT → RESET → BALL", "detail": "주자가 뛰어 커버를 시작했더라도 타격이 이루어지면 기존 임무를 잠시 끊고 공의 위치와 내 책임을 다시 판단한다.", "diagram": "contact-2b"}, {"id": "errorreset", "title": "실책·악송구 리셋", "body": "BALL → RUNNER → BASE → NEXT", "detail": "첫 실수는 이미 일어났다. 공을 다시 확보하고 추가 진루를 막은 뒤 다음 플레이를 준비한다."}, {"id": "force", "title": "포스인가 태그인가?", "body": "포스 상황을 투구 전에 확인한다.", "detail": "R1이면 2루 포스, R1·R2이면 3루까지 포스, 만루면 홈까지 포스가 있다. R2 또는 R3만 있으면 다음 베이스는 일반적인 포스가 아니다."}, {"id": "call", "title": "좋은 콜", "body": "짧게 · 일찍 · 명확하게 · 필요한 것만", "detail": "원아웃, 병살 있어, 내꺼, 둘, 홈, 컷처럼 팀원이 바로 행동할 수 있는 정보를 준다."}];
