const BO={"empty": [["선두타자의 쉬운 아웃을 확실하게.", "땅볼은 1루, 플라이는 포구 우선. 단타를 2루타로 만들지 않는다."], ["두 번째 아웃을 확실하게.", "무리한 송구보다 재현 가능한 플레이를 선택한다."], ["가장 쉬운 아웃 하나면 이닝 종료.", "평범한 플레이를 어렵게 만들지 않는다."]], "r1": [["병살 가능성을 먼저 본다.", "빠른 땅볼이면 2루 선행주자부터. 늦으면 1루 하나. 도루 커버는 팀 약속 확인."], ["병살이면 이닝 종료.", "하지만 애매한 타구에서 0아웃 플레이를 만들지 말고 확실한 하나를 확보한다."], ["가장 쉬운 포스 하나면 종료.", "1루든 2루든 가까운 확실한 아웃. 병살은 필요 없다."]], "r2": [["포스 없음. 아웃 + 추가 진루 제한.", "무리한 태그보다 1루 아웃이 좋은 경우가 많다. 외야 타구는 3루·홈 진루 가능성 확인."], ["아웃 하나의 가치가 크다.", "내야 땅볼은 확실한 아웃을 우선하고, 외야 안타는 홈 승부 기대값을 본다."], ["1루 아웃이면 이닝 종료.", "외야 안타면 R2는 바로 홈을 노릴 수 있으므로 OF–CUT–C–P 백업을 준비한다."]], "r3": [["실점 방지 전략을 먼저 정한다.", "한 점을 반드시 막으면 전진수비, 아웃 확보가 우선이면 일반 깊이. 팀 지시를 우선한다."], ["희생플라이와 내야 땅볼 모두 득점 상황.", "포구 전부터 홈 플레이 가능성을 생각한다."], ["주자보다 타자주자 아웃.", "평범한 땅볼 1루 아웃 또는 플라이 포구면 이닝 종료."]], "r12": [["3루에도 포스가 있다.", "3B 근처 빠른 땅볼은 3루 포스 가능. 번트 로테이션을 경기 전에 확인한다."], ["병살 가능 + 3루 포스.", "타구 위치에 가장 자연스러운 포스를 선택하고 첫 아웃을 확실히 한다."], ["어느 포스든 하나면 종료.", "3루·2루·1루 중 가장 쉬운 곳. 앞선 주자를 억지로 잡으려 하지 않는다."]], "r13": [["1·3루 도루 시스템이 핵심.", "R1 도루 때 R3 홈 스틸 가능. 팀의 직접송구·컷·송구보류 약속을 따른다."], ["병살과 실점 방지를 함께 본다.", "점수 상황에 따라 홈 우선 또는 병살 선택. 외야 플라이는 R3 태그업 대비."], ["홈보다 쉬운 포스 하나.", "R3 득점에 시선이 끌려 어려운 홈 송구를 하지 않는다."]], "r23": [["포스 없음. 두 득점권 주자.", "전진수비 여부를 정하고, 아웃이 어려우면 최소 한 베이스를 막는다."], ["희생플라이 한 번으로 실점 가능.", "R3만 보지 말고 R2의 3루 진루도 관리한다."], ["타자주자 아웃이면 종료.", "안타가 되면 두 주자 득점 가능성이 높으므로 뒤 주자와 타자주자의 추가 진루를 제한한다."]], "loaded": [["홈 포함 모든 베이스 포스.", "무조건 홈이 아니라 가장 높은 성공확률의 포스·병살 경로를 선택한다."], ["병살이면 이닝 종료.", "홈-1루, 2루-1루 등 타구 위치에 맞는 첫 아웃을 택한다."], ["가장 가까운 포스 하나.", "홈으로 어려운 송구를 할 이유가 없다. 3루·2루·1루 어디든 확실한 포스면 종료."]]};
const PLAY=[{"id": "steal", "title": "도루", "sub": "주자 스타트 → 커버 → CONTACT 여부 확인", "tags": ["TEAM", "CORE"], "bullets": ["커버 담당을 경기 전에 확인한다.", "투수가 던진 뒤 주자 스타트를 확인한다.", "타자가 타격하면 CONTACT RESET.", "송구가 빠지면 다음 베이스부터 막는다."], "coach": "주자가 뛰었다고 타자를 잊지 마.", "diagram": "contact-2b"}, {"id": "doubleplay", "title": "병살", "sub": "첫 아웃을 확실히 만든 뒤 두 번째 아웃", "tags": ["OPTION"], "bullets": ["포구 전에 병살 가능성을 안다.", "첫 송구가 늦으면 1루 하나로 전환한다.", "피벗 야수는 베이스 처리 뒤 주자의 진로에서 빠져나온다."], "coach": "병살은 두 아웃을 욕심내는 플레이가 아니라 첫 아웃이 빠른 플레이야.", "diagram": "6-4-3"}, {"id": "bunt", "title": "희생번트", "sub": "한 명은 공, 나머지는 빈 베이스", "tags": ["TEAM", "OPTION"], "bullets": ["“번트!” 콜을 일찍 한다.", "차지하는 야수가 비운 베이스를 누가 채울지 팀 약속을 따른다.", "선행주자 아웃이 명확하지 않으면 1루 확실한 아웃으로 바꾼다."], "coach": "번트 수비는 공 잡는 기술보다 로테이션이야.", "diagram": "r2-bunt"}, {"id": "rundown", "title": "런다운", "sub": "쫓지 말고 몰고, 송구는 적게", "tags": ["CORE"], "bullets": ["두 야수가 중심이 되어 거리를 압축한다.", "주자를 원래 베이스보다 다음 아웃이 쉬운 방향으로 몰아간다.", "송구 횟수가 늘수록 실수 가능성이 커진다."], "coach": "주자를 잡으러 뛰지 말고 도망갈 공간을 없애.", "diagram": "rundown"}, {"id": "cutoff", "title": "컷오프·릴레이", "sub": "공–컷맨–목표 베이스를 한 선으로", "tags": ["TEAM"], "bullets": ["공 쪽으로 무작정 달려가지 않는다.", "목표 베이스와 외야수 사이의 송구선을 만든다.", "컷/노컷 콜과 담당자는 팀 약속을 따른다."], "coach": "컷맨은 공 가까운 사람이 아니라 송구선 위의 사람이야.", "diagram": "home-relay"}, {"id": "wildpitch", "title": "폭투·포일 + R3", "sub": "C는 공, P는 홈", "tags": ["CORE"], "bullets": ["포수는 공을 확보한다.", "투수는 홈 커버로 이동한다.", "세이프가 확실하면 공을 던져 추가 진루를 만들지 않는다."], "coach": "둘 다 공으로 가면 홈이 빈다.", "diagram": "wildpitch-r3"}, {"id": "tagup", "title": "외야 플라이 + 태그업", "sub": "포구 전에 주자를 보고 송구를 준비", "tags": ["RULE", "OPTION"], "bullets": ["포구 전 R3/R2의 태그업 가능성을 본다.", "잡는 순간이 아니라 포구 전부터 송구 풋워크를 만든다.", "잡을 수 없는 홈 승부라면 뒤 주자를 제한한다."], "coach": "플라이를 잡는 순간 수비가 끝나는 게 아니라 다음 플레이가 시작된다.", "diagram": "tagup-r3"}, {"id": "overthrow", "title": "악송구", "sub": "BALL → RUNNER → BASE → NEXT", "tags": ["CORE"], "bullets": ["공 위치를 가장 먼저 확보한다.", "누가 어디까지 갔는지 본다.", "가장 위험한 다음 베이스를 막는다."], "coach": "첫 실수보다 두 번째 실수를 막는 게 중요하다.", "diagram": "first-overthrow"}, {"id": "infieldfly", "title": "인필드플라이", "sub": "선언돼도 플레이는 끝나지 않는다", "tags": ["RULE"], "bullets": ["0·1아웃, R1·R2 또는 만루에서 적용될 수 있다.", "타자는 아웃이어도 주자는 위험을 감수하고 움직일 수 있다.", "선수는 심판 콜을 확인하고 공을 확실히 처리한다."], "coach": "규칙을 알수록 더 차분하게 그냥 잡으면 된다."}, {"id": "appeal", "title": "태그업·베이스 미터치 어필", "sub": "봤다면 바로 알리고 플레이 종료 전 처리", "tags": ["RULE"], "bullets": ["태그업이 너무 빨랐거나 베이스를 밟지 않은 것을 봤다면 즉시 공유한다.", "어필에는 시점과 절차가 있으므로 감독·심판과 함께 처리한다.", "이닝 종료처럼 보여도 바로 필드를 떠나지 않는다."], "coach": "봤다면 말해. 심판이 알아서 잡아주길 기다리지 마."}, {"id": "hitrun", "title": "히트앤런", "sub": "주자 스타트에 끌려가지 않는 상황 전환", "tags": ["CORE"], "bullets": ["도루와 비슷하게 주자가 먼저 움직인다.", "타격 순간 CONTACT RESET.", "비어진 수비 위치로 타구가 오기 쉬우므로 몸을 완전히 베이스로 돌리지 않는다."], "coach": "주자 움직임은 정보고, 타구는 새로운 플레이야.", "diagram": "contact-2b"}];
const READ_PARTS=[{"id": "0", "title": "공은 잘 잡는데 왜 수비가 어려울까", "sub": "캐치볼과 실제 수비 사이에는 판단이 있다.", "sections": [["수비는 포구와 송구보다 크다", "캐치볼을 잘하고 평범한 땅볼을 잡을 수 있어도 경기에서는 주자, 아웃카운트, 베이스 커버, 백업이 동시에 움직인다. 그래서 “공을 잡을 줄 안다”와 “수비를 할 줄 안다” 사이에는 큰 간격이 있다."], ["경험을 압축한다", "사회인야구에서는 매주 같은 포지션을 서지 못하고 팀 훈련도 제한적이다. 모든 상황을 직접 실수해서 배울 필요는 없다. 이 책은 경기에서 열 번 당해서 배울 것을 한 번 읽고 알아보게 만드는 것이 목표다."], ["결과와 과정을 나눈다", "안타가 됐다고 항상 나쁜 수비는 아니고 아웃이 됐다고 항상 좋은 판단도 아니다. 위치·첫 스텝·판단·포구·송구·커버를 나눠 봐야 실제 실력이 는다."]]}, {"id": "1", "title": "좋은 수비수의 머릿속", "sub": "공이 오기 전에 수비를 시작한다.", "sections": [["OUT → RUNNER → SCORE → BATTER → PLAY", "매 투구 전에 다섯 가지를 짧게 확인한다. 몇 아웃인지, 주자가 어디 있는지, 점수 상황이 어떤지, 타자 특성이 무엇인지, 공이 내게 오면 무엇을 할지 생각한다."], ["확실한 아웃", "좋은 수비는 가장 멋진 주자를 잡는 것이 아니라 가장 확실한 아웃을 놓치지 않는 것에서 시작한다. 병살이나 선행주자 승부는 조건이 보일 때 추가한다."], ["CONTACT RESET", "주자 스타트로 커버를 시작했더라도 타격이 발생하면 이전 임무를 재평가한다. 내 책임 타구면 공이 먼저고, 아니면 다시 커버·백업·컷으로 간다."], ["내 공이 아니면 내 역할이 시작된다", "공이 나에게 오지 않았다는 것은 플레이에서 제외됐다는 뜻이 아니다. 오히려 베이스 커버, 컷, 백업, 다음 송구라는 새로운 역할이 시작된다."]]}, {"id": "2", "title": "말하는 수비수", "sub": "좋은 콜은 주변 선수의 판단 시간을 줄인다.", "sections": [["짧고 일찍 말한다", "“원아웃”, “병살 있어”, “내꺼”, “둘”, “홈”, “컷”처럼 행동으로 바로 연결되는 말을 쓴다. 큰 목소리보다 타이밍과 명확성이 중요하다."], ["실책 뒤에는 현재를 말한다", "“왜 그랬어?”보다 “원아웃이야. 하나 잡자.”가 경기에는 도움이 된다. 기술적인 복기는 이닝이나 경기 뒤에 한다."], ["수비 리더", "포수는 전체, 유격수는 내야, 중견수는 외야의 정보를 정리하는 역할을 맡기 좋다. 리더는 모든 것을 지시하는 사람이 아니라 주변 판단을 단순하게 만드는 사람이다."]]}, {"id": "3", "title": "모든 야수가 갖춰야 할 실전 기본기", "sub": "좋은 자세는 다음 판단을 빠르게 한다.", "sections": [["준비 자세와 첫 스텝", "발뒤꿈치에 고정되지 않고 타구에 반응할 수 있는 중심을 만든다. 첫 스텝은 빠르기보다 정확한 방향이 중요하다."], ["땅볼", "좋은 수비수는 공이 올 때까지 기다리지 않고 좋은 바운드를 만나러 간다. 정면·포핸드·백핸드·숏바운드를 상황에 따라 사용한다."], ["플라이", "낙하지점 판단, 우선권 콜, 태그업 주자, 포구 후 송구까지 한 플레이로 본다."], ["커버·컷·백업", "공을 처리한 선수의 자리가 비고 송구에는 항상 실패 가능성이 있다. 그래서 공이 없는 야수의 움직임이 팀 수비의 안정성을 결정한다."]]}, {"id": "4", "title": "포지션별 완전정복", "sub": "9개 포지션은 같은 수비 원칙을 서로 다른 각도에서 실행한다.", "sections": [["배터리와 1루", "C는 전체 정보를 보고, P는 타격 순간 야수가 되며, 1B는 동료의 송구를 살린다."], ["키스톤과 좌측 내야", "2B와 SS는 R1·병살·도루에서 역할을 맞추고, 3B는 짧은 반응과 번트·R2 상황을 책임진다."], ["외야 3인", "LF·CF·RF는 잡는 것뿐 아니라 단타를 단타로 끝내고, 갭과 펜스, 중계와 백업으로 추가 베이스를 지운다."]]}, {"id": "5", "title": "Base-Out 24상황", "sub": "8개 주자 상태 × 3개 아웃카운트를 자동화한다.", "sections": [["2아웃은 단순해진다", "대부분의 상황에서 가장 쉬운 아웃 하나면 이닝이 끝난다. 홈의 주자에 시선이 끌려 어려운 송구를 만들지 않는다."], ["포스를 먼저 본다", "R1이면 2루, R1·R2면 3루까지, 만루면 홈까지 포스가 있다. R2·R3만 있는 상황은 다음 베이스 포스가 아니다."], ["R3 상황은 전략이다", "실점을 반드시 막아야 하는지, 아웃과 한 점을 교환해도 되는지 점수와 이닝에 따라 수비 깊이가 달라진다."]]}, {"id": "6", "title": "특수 상황 백과", "sub": "도루·번트·런다운·인필드플라이·어필까지.", "sections": [["주자가 먼저 움직이는 플레이", "도루·히트앤런에서 가장 중요한 것은 CONTACT가 발생했을 때 상황을 다시 읽는 것이다."], ["번트·스퀴즈", "공으로 가는 야수와 비는 베이스를 동시에 설계해야 한다. 팀 로테이션이 없으면 아무리 좋은 개인 수비도 빈 베이스를 만든다."], ["희귀 상황", "베이스 미터치, 주자 추월, 같은 베이스의 두 주자, 고의낙구처럼 자주 나오지 않는 상황은 판정을 스스로 끝내지 말고 공을 확보하고 심판 콜을 확인한다."]]}, {"id": "7", "title": "9명이 움직이는 팀 디펜스", "sub": "한 명은 공으로, 나머지는 다음 플레이로 간다.", "sections": [["BALL / RELAY / BASE / BACKSIDE / BACKUP", "타구 하나에 아홉 명이 같은 공을 쫓지 않는다. 공 처리, 중계, 베이스, 반대편 이동, 악송구 백업으로 역할을 나눈다."], ["컷오프", "컷맨은 외야수에게 가까운 사람이 아니라 목표 베이스와 송구선을 만드는 사람이다. 정확한 담당은 팀 시스템을 따른다."], ["첫 송구 뒤가 위험하다", "홈이나 3루로 첫 송구가 간 뒤 타자주자와 뒤 주자가 움직인다. 첫 송구가 끝나도 베이스를 비우지 않는다."]]}, {"id": "8", "title": "사회인야구에는 사회인야구의 수비가 있다", "sub": "프로의 원리를 우리 성공확률에 맞게 번역한다.", "sections": [["이론상 최선보다 기대값", "강한 송구, 다이빙, 병살 모두 성공확률과 실패 비용을 같이 본다. 4부에서는 확실한 한 아웃과 공을 앞에 막는 플레이가 매우 큰 가치가 있다."], ["환경 변수", "인조잔디, 야간 조명, 젖은 공, 작은 백스톱, 불규칙 바운드가 실제 수비를 바꾼다. 경기 전 구장 확인도 수비 기술이다."], ["팀원 실력차", "정교한 프로식 로테이션보다 모두가 기억할 수 있는 단순한 팀 약속이 더 잘 작동할 수 있다."]]}, {"id": "9", "title": "실책 이후의 야구", "sub": "첫 실수보다 다음 플레이가 더 중요하다.", "sections": [["BALL → RUNNER → BASE → NEXT", "실책 순간 분석을 시작하지 않는다. 공을 확보하고 주자를 보고 베이스를 막은 뒤 다음 플레이로 돌아온다."], ["두 번째 실수를 막는다", "첫 실수를 만회하려고 무리한 송구를 하면 실수가 빅이닝으로 커진다. 만회가 아니라 다음 아웃을 만든다."], ["경기 후 복기", "위치·첫 스텝·판단·포구·송구·커버·백업·콜을 나눠 보고 다음 경기 과제는 1~2개만 정한다."]]}, {"id": "10", "title": "팀이 믿는 수비수", "sub": "완벽함보다 반복 가능한 신뢰.", "sections": [["쉬운 아웃을 소중히", "팀의 신뢰는 호수비보다 평범한 공을 반복해서 처리하는 데서 먼저 생긴다."], ["공이 없을 때도 유용하다", "백업, 커버, 컷, 콜은 기록에는 남지 않아도 실점과 추가 진루를 막는다."], ["성장", "처음에는 무리였던 플레이가 반복 가능한 플레이가 되는 것이 수비력의 성장이다."], ["마지막 기준", "좋은 수비수는 모든 공을 잡는 선수가 아니다. 공이 어디로 가든 팀이 그 선수를 믿을 수 있는 선수다."]]}];
const DIAGRAMS={"contact-2b": {"title": "R1 도루 중 타격 — CONTACT RESET", "stages": [{"title": "① 주자 스타트", "active": ["2B", "R1"], "moves": [["2B", [62, 43], [52, 36]], ["R1", [73, 60], [52, 38]]], "runner": [["R1", [73, 60], [52, 38]]]}, {"title": "② CONTACT — 타구가 2B 방향", "active": ["2B"], "ball": [[50, 83], [66, 48]], "moves": [["2B", [54, 39], [65, 49]]], "note": "기존 커버 임무를 끊고 BALL FIRST"}]}, "contact-3b": {"title": "R2 3루 도루 중 타격 — CONTACT RESET", "stages": [{"title": "① R2 스타트", "active": ["3B", "R2"], "moves": [["3B", [27, 57], [26, 59]]], "runner": [["R2", [50, 35], [27, 57]]]}, {"title": "② CONTACT — 3·유간 타구", "active": ["3B"], "ball": [[50, 83], [33, 49]], "moves": [["3B", [26, 58], [33, 49]]], "note": "태그 생각보다 내 책임 타구가 먼저"}]}, "4-6-3": {"title": "4-6-3 병살", "stages": [{"title": "2B → SS → 1B", "active": ["2B", "SS", "1B"], "ball": [[50, 83], [62, 47]], "moves": [["2B", [62, 43], [59, 47]]], "throws": [[[59, 47], [49, 35]], [[49, 35], [74, 58]]], "runner": [["R1", [74, 59], [50, 35]]]}]}, "6-4-3": {"title": "6-4-3 병살", "stages": [{"title": "SS → 2B → 1B", "active": ["SS", "2B", "1B"], "ball": [[50, 83], [38, 46]], "moves": [["SS", [38, 43], [39, 47]]], "throws": [[[39, 47], [51, 35]], [[51, 35], [74, 58]]], "runner": [["R1", [74, 59], [50, 35]]]}]}, "p-1b": {"title": "P–1B 사이 타구와 1루 커버", "stages": [{"title": "① 1B가 공 처리", "active": ["1B", "P"], "ball": [[50, 83], [67, 61]], "moves": [["1B", [73, 58], [67, 61]], ["P", [50, 62], [74, 58]]], "throws": [[[67, 61], [74, 58]]]}, {"title": "② P가 공 처리", "active": ["P", "1B"], "ball": [[50, 83], [59, 64]], "moves": [["P", [50, 62], [59, 64]], ["1B", [70, 61], [74, 58]]], "throws": [[[59, 64], [74, 58]]]}]}, "r2-bunt": {"title": "R2 번트 — 예시 로테이션", "stages": [{"title": "3B 차지 / SS 3루 커버 예시", "active": ["C", "P", "1B", "3B", "SS", "R2"], "ball": [[50, 83], [40, 72]], "moves": [["3B", [27, 58], [39, 70]], ["SS", [38, 43], [26, 58]], ["P", [50, 62], [43, 69]], ["1B", [73, 58], [62, 70]]], "runner": [["R2", [50, 35], [27, 58]]], "note": "TEAM: 정확한 담당은 우리 팀 약속 우선"}]}, "r13-steal": {"title": "R1·R3 더블스틸", "stages": [{"title": "R1 스타트 순간 R3 확인", "active": ["C", "SS", "2B", "R1", "R3"], "runner": [["R1", [74, 59], [50, 35]], ["R3", [26, 59], [50, 83]]], "moves": [["SS", [38, 43], [50, 35]], ["2B", [62, 43], [53, 37]]], "note": "TEAM: 직접송구/컷/보류는 팀 시스템"}]}, "r2-lf-single": {"title": "R2 좌전안타 → 홈 송구", "stages": [{"title": "LF → CUT → HOME / P 백업", "active": ["LF", "SS", "C", "P", "R2"], "ball": [[50, 83], [22, 28]], "throws": [[[22, 28], [38, 47]], [[38, 47], [50, 83]]], "moves": [["P", [50, 62], [50, 92]]], "runner": [["R2", [50, 35], [50, 83]]], "note": "홈 승부가 낮으면 타자주자 추가 진루 제한"}]}, "r1-rf-single": {"title": "R1 우전안타 → 3루 승부", "stages": [{"title": "RF가 R1의 3루 진루를 제한", "active": ["RF", "SS", "3B", "R1"], "ball": [[50, 83], [79, 29]], "throws": [[[79, 29], [55, 46]], [[55, 46], [26, 59]]], "runner": [["R1", [74, 59], [26, 59]]], "note": "늦으면 컷해서 타자주자를 2루에 묶는다"}]}, "home-relay": {"title": "외야 → 컷맨 → 홈", "stages": [{"title": "공–컷–홈을 한 선으로", "active": ["CF", "SS", "C", "P"], "throws": [[[50, 18], [45, 48]], [[45, 48], [50, 83]]], "moves": [["P", [50, 62], [50, 92]]], "note": "TEAM: 컷 담당자는 팀 시스템에 따라 다름"}]}, "wildpitch-r3": {"title": "폭투 + R3", "stages": [{"title": "C는 공 / P는 홈", "active": ["C", "P", "R3"], "ball": [[50, 83], [67, 91]], "moves": [["C", [50, 83], [67, 91]], ["P", [50, 62], [50, 83]]], "runner": [["R3", [26, 59], [50, 83]]]}]}, "first-overthrow": {"title": "1루 악송구와 RF 백업", "stages": [{"title": "RF가 충분한 깊이에서 백업", "active": ["1B", "RF"], "throws": [[[38, 47], [78, 58]]], "moves": [["RF", [79, 29], [88, 65]]], "note": "1B 바로 뒤가 아니라 빠진 공을 막을 깊이"}]}, "rundown": {"title": "런다운 — 송구를 줄이고 공간 압축", "stages": [{"title": "두 야수가 주자를 몰아간다", "active": ["SS", "3B", "R2"], "moves": [["SS", [43, 44], [34, 50]], ["3B", [27, 58], [31, 55]]], "runner": [["R2", [36, 49], [31, 55]]], "note": "쫓지 말고 몰아. 송구는 적게."}]}, "tagup-r3": {"title": "외야 플라이 + R3 태그업", "stages": [{"title": "포구 전부터 홈 송구 준비", "active": ["LF", "C", "P", "R3"], "ball": [[50, 83], [22, 23]], "throws": [[[22, 23], [40, 48]], [[40, 48], [50, 83]]], "runner": [["R3", [26, 59], [50, 83]]], "moves": [["P", [50, 62], [50, 92]]]}]}};

const view=document.querySelector('#view'), crumb=document.querySelector('#crumb');
const searchDialog=document.querySelector('#searchDialog'), searchInput=document.querySelector('#searchInput'), searchResults=document.querySelector('#searchResults');
let state={route:'home',params:{}};
const POS={C:[50,84],P:[50,62],'1B':[74,58],'2B':[62,43],'3B':[26,58],SS:[38,43],LF:[20,24],CF:[50,15],RF:[80,24]};
const BASEPOS={H:[50,84],'1':[74,58],'2':[50,35],'3':[26,58]};
function esc(s=''){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));}
function routeTo(route,params={}){state={route,params};render();window.scrollTo({top:0,behavior:'instant'});}
function getFavs(){try{return JSON.parse(localStorage.getItem('def-favs')||'[]')}catch{return []}}
function getRecent(){try{return JSON.parse(localStorage.getItem('def-recent')||'[]')}catch{return []}}
function addRecent(item){let a=getRecent().filter(x=>x.key!==item.key);a.unshift(item);localStorage.setItem('def-recent',JSON.stringify(a.slice(0,6)));}
function toggleFav(key,title){let a=getFavs();const has=a.some(x=>x.key===key);a=has?a.filter(x=>x.key!==key):[{key,title},...a];localStorage.setItem('def-favs',JSON.stringify(a));render();}
function favButton(key,title){const on=getFavs().some(x=>x.key===key);return `<button class="action-btn" data-fav-key="${esc(key)}" data-fav-title="${esc(title)}">${on?'★ 저장됨':'☆ 저장'}</button>`}
function shareButton(title){return `<button class="action-btn primary" data-share-title="${esc(title)}">↗ 공유</button>`}
function tagsHTML(tags=[]){return tags.length?`<div class="tag-group">${tags.map(t=>`<span class="tag ${t}">${t}</span>`).join('')}</div>`:''}
function relatedButtons(items){return `<div class="related"><div class="section-title">같이 보기</div><div class="related-buttons">${items.map(x=>`<button data-go="${x.route}" data-param='${JSON.stringify(x.params||{})}'>${x.label}</button>`).join('')}</div></div>`}
function diamondHTML(bases=[]){return `<svg class="diamond" viewBox="0 0 100 90" aria-hidden="true"><path d="M50 78 18 46 50 14 82 46Z" fill="none" stroke="#9ba6a1" stroke-width="2"/><rect x="47" y="73" width="7" height="7" transform="rotate(45 50.5 76.5)" class="base-dot"/><rect x="78" y="42" width="7" height="7" transform="rotate(45 81.5 45.5)" class="base-dot ${bases.includes(1)?'on':''}"/><rect x="47" y="10" width="7" height="7" transform="rotate(45 50.5 13.5)" class="base-dot ${bases.includes(2)?'on':''}"/><rect x="15" y="42" width="7" height="7" transform="rotate(45 18.5 45.5)" class="base-dot ${bases.includes(3)?'on':''}"/></svg>`}
function markerDefs(){return `<defs><marker id="arrB" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L0,6 L6,3 z" fill="#3d6eb4"/></marker><marker id="arrG" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L0,6 L6,3 z" fill="#39895c"/></marker><marker id="arrO" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L0,6 L6,3 z" fill="#d87b2b"/></marker><marker id="arrR" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L0,6 L6,3 z" fill="#c84a3d"/></marker></defs>`}
function fieldBase(){return `<rect width="100" height="100" rx="5" fill="#eaf1e5"/><path d="M50 86 L12 48 Q20 11 50 8 Q80 11 88 48 L50 86" fill="#d7e5cf" stroke="#bdceb5" stroke-width=".7"/><path d="M50 84 26 58 50 35 74 58Z" fill="#e8d9b7" stroke="#c9b58c" stroke-width=".8"/><path d="M50 84 50 35 M26 58 74 58" stroke="#d1bea0" stroke-width=".5" opacity=".6"/><circle cx="50" cy="62" r="2.6" fill="#d9c59b"/><circle cx="50" cy="84" r="1.8" fill="#fff" stroke="#9b9b8c"/><rect x="71.5" y="55.5" width="5" height="5" transform="rotate(45 74 58)" fill="#fff"/><rect x="47.5" y="32.5" width="5" height="5" transform="rotate(45 50 35)" fill="#fff"/><rect x="23.5" y="55.5" width="5" height="5" transform="rotate(45 26 58)" fill="#fff"/>`}
function line(a,b,color,marker,dash=''){return `<line x1="${a[0]}" y1="${a[1]}" x2="${b[0]}" y2="${b[1]}" stroke="${color}" stroke-width="1.8" stroke-linecap="round" ${dash?`stroke-dasharray="${dash}"`:''} marker-end="url(#${marker})"/>`}
function player(label,coord,active=false){const [x,y]=coord;return `<g><circle cx="${x}" cy="${y}" r="${active?3.9:3.2}" fill="${active?'#0d3328':'#fff'}" stroke="#0d3328" stroke-width=".8"/><text x="${x}" y="${y+1.1}" font-size="${active?2.8:2.5}" text-anchor="middle" font-weight="900" fill="${active?'#fff':'#0d3328'}">${label}</text></g>`}
function diagramStage(stage){let s=`<svg class="field-svg" viewBox="0 0 100 100">${markerDefs()}${fieldBase()}`;const active=stage.active||[];Object.entries(POS).forEach(([k,v])=>s+=player(k,v,active.includes(k)));(stage.runner||[]).forEach(([name,a,b])=>{s+=line(a,b,'#d87b2b','arrO','3 2');s+=`<circle cx="${a[0]}" cy="${a[1]}" r="3" fill="#d87b2b"/><text x="${a[0]}" y="${a[1]+1}" font-size="2.4" text-anchor="middle" fill="#fff" font-weight="900">${name}</text>`});(stage.moves||[]).forEach(([name,a,b])=>s+=line(a,b,'#3d6eb4','arrB','4 2'));(stage.throws||[]).forEach(([a,b])=>s+=line(a,b,'#39895c','arrG'));if(stage.ball){const [a,b]=stage.ball;s+=line(a,b,'#c84a3d','arrR');s+=`<circle cx="${a[0]}" cy="${a[1]}" r="1.6" fill="#c84a3d"/>`;}s+='</svg>';return s;}
function diagramHTML(id){const d=DIAGRAMS[id];if(!d)return '';return `<div class="diagram-card"><div class="diagram-head"><b>${d.title}</b><span>전술도</span></div>${d.stages.map(st=>`<div class="diagram-stage"><div class="diagram-stage-title">${st.title}</div>${diagramStage(st)}${st.note?`<div class="small" style="margin:6px 2px">※ ${st.note}</div>`:''}</div>`).join('')}<div class="legend"><span><i class="ball"></i>타구</span><span><i class="move"></i>야수 이동</span><span><i class="throw"></i>송구</span><span><i class="runner"></i>주자</span></div></div>`}
function positionById(id){return POSITIONS.find(p=>p.id===id)||POSITIONS[0]}
function playById(id){return PLAY.find(p=>p.id===id)||PLAY[0]}
function homeView(){crumb.textContent='HOME';const rec=getRecent();return `<section class="hero"><div class="eyebrow">MOBILE BASEBALL LAB</div><h1>오태니표헤이의<br>사회인야구 수비의 디테일</h1><p class="lead">경험하기 전에 배우는 실전 팀 디펜스.<br>읽을 때는 야구를 이해하고, 경기장에서는 10초 안에 답을 찾습니다.</p></section><div class="grid two"><button class="mode-card" data-go="read"><div class="mode-icon">📖</div><b>제대로 배우기</b><span>PART 0~10을 책처럼 읽기</span></button><button class="mode-card" data-go="game"><div class="mode-icon">⚾</div><b>경기장에서 바로 찾기</b><span>포지션·주자·플레이로 즉시 찾기</span></button></div><div class="section-title">바로 찾기</div><div class="grid two"><button class="nav-card" data-go="positions"><strong>내 포지션</strong><span class="sub">9개 포지션 상세 수비</span></button><button class="nav-card" data-go="situations"><strong>주자·아웃 상황</strong><span class="sub">24 Base-Out</span></button><button class="nav-card" data-go="plays"><strong>플레이</strong><span class="sub">도루·병살·번트·컷오프</span></button><button class="nav-card" data-go="core"><strong>CORE 원칙</strong><span class="sub">CONTACT RESET 등</span></button></div><div class="section-title">대표 전술도</div><div class="quick-list"><button class="quick-item" data-go="core-page" data-param='{"id":"contact"}'><b>CONTACT RESET <span class="tag CORE">CORE</span></b><span>주자 스타트 중 타격이 나왔을 때</span></button><button class="quick-item" data-go="position-topic" data-param='{"pos":"2b","idx":4}'><b>4-6-3 병살</b><span>2B → SS → 1B</span></button><button class="quick-item" data-go="play" data-param='{"id":"cutoff"}'><b>홈 송구 컷오프 <span class="tag TEAM">TEAM</span></b><span>공–컷맨–홈 송구선</span></button></div>${rec.length?`<div class="section-title">최근 본 페이지</div><div class="quick-list">${rec.map(r=>`<button class="quick-item" data-route-key="${esc(r.key)}"><b>${esc(r.title)}</b><span>다시 열기</span></button>`).join('')}</div>`:''}<div class="install-note"><div class="emoji">📱</div><div><b>네 팀 단톡방에는 링크 하나만</b><div class="small">자주 보는 팀원은 Safari/Chrome에서 홈 화면에 추가하면 앱처럼 꺼내볼 수 있습니다.</div></div></div>`}
function gameView(){crumb.textContent='경기장에서 바로 찾기';return `<section class="hero"><div class="eyebrow">GAME MODE</div><h2>지금 필요한 것만 보세요.</h2><p class="lead">최대 3번의 선택으로 필요한 수비 상황에 도달합니다.</p></section><div class="grid two"><button class="nav-card" data-go="positions"><strong>① 오늘 포지션</strong><span class="sub">30초 요약 + 상세</span></button><button class="nav-card" data-go="situations"><strong>② 주자·아웃</strong><span class="sub">24 Base-Out</span></button><button class="nav-card" data-go="plays"><strong>③ 플레이</strong><span class="sub">도루·번트·컷·런다운</span></button><button class="nav-card" data-go="core"><strong>④ 머리가 하얘졌다</strong><span class="sub">CORE 원칙으로 RESET</span></button></div>`}
function positionsView(){crumb.textContent='HOME > 포지션';return `<section class="hero"><div class="eyebrow">POSITION QUICK FIND</div><h2>오늘 어디 보세요?</h2><p class="lead">30초 복습 뒤 필요한 상황을 세부 메뉴에서 바로 찾습니다.</p></section><div class="grid three">${POSITIONS.map(p=>`<button class="nav-card" data-go="position" data-param='{"id":"${p.id}"}'><strong>${p.code} ${p.name}</strong><span class="sub">${p.tag}</span></button>`).join('')}</div>`}
function positionView(id){const p=positionById(id),topics=POSITION_DATA[id]||[];const key=`position:${id}`;crumb.textContent=`포지션 > ${p.code} ${p.name}`;addRecent({key,title:`${p.code} ${p.name}`});return `<section class="hero"><div class="position-hero"><div class="pos-badge">${p.code}</div><div><div class="eyebrow">30초 포지션 복습</div><h1>${p.name}</h1><p class="lead">${p.tag}</p></div></div></section><div class="content-card"><div class="check-list">${p.summary.map((s,i)=>`<div class="check-line"><span class="check-dot">${i+1}</span><div>${s}</div></div>`).join('')}</div><div class="coach">“${p.line}”</div></div><div class="page-actions">${favButton(key,`${p.code} ${p.name}`)}${shareButton(`${p.code} ${p.name}`)}</div><div class="section-title">세부 수비</div><div class="section-sub">각 항목을 눌러 실제 움직임·실수·전술도를 확인하세요.</div><div class="topic-grid">${topics.map((t,i)=>`<button class="topic-card" data-go="position-topic" data-param='{"pos":"${id}","idx":${i}}'><div class="topic-head"><b>${t.title}</b><span>›</span></div><span>${t.teaser}</span>${tagsHTML(t.tags)}</button>`).join('')}</div>${relatedButtons([{label:'Base-Out 찾기',route:'situations'},{label:'플레이 찾기',route:'plays'},{label:'CORE 원칙',route:'core'}])}`}
function positionTopic(pos,idx){const p=positionById(pos),t=(POSITION_DATA[pos]||[])[Number(idx)];if(!t)return positionView(pos);const key=`pt:${pos}:${idx}`;crumb.textContent=`${p.code} ${p.name} > ${t.title}`;addRecent({key,title:`${p.code} ${t.title}`});return `<section class="hero"><div class="eyebrow">${p.code} · POSITION DETAIL</div><h1>${t.title}</h1><p class="lead">${t.teaser}</p></section>${tagsHTML(t.tags)}${t.diagram?diagramHTML(t.diagram):''}<div class="content-card"><div class="steps">${t.bullets.map((b,i)=>`<div class="step"><b>${i+1}</b><div>${b}</div></div>`).join('')}</div>${(t.mistakes||[]).map(m=>`<div class="mistake"><b>많이 하는 실수</b><br>${m}</div>`).join('')}${t.coach?`<div class="coach">“${t.coach}”</div>`:''}</div><div class="page-actions">${favButton(key,`${p.code} ${t.title}`)}${shareButton(`${p.code} ${t.title}`)}</div>${relatedButtons([{label:`${p.code} 전체`,route:'position',params:{id:pos}},{label:'주자 상황',route:'situations'},{label:'플레이',route:'plays'}])}`}
function situationsView(){crumb.textContent='HOME > 주자 상황';return `<section class="hero"><div class="eyebrow">BASE-OUT QUICK FIND</div><h2>지금 주자는 어디에 있나요?</h2><p class="lead">주자 상태를 고르고 다음 화면에서 아웃카운트를 누릅니다.</p></section><div class="diamond-wrap">${BASE_STATES.map(s=>`<button class="diamond-card" data-go="situation" data-param='{"state":"${s.id}"}'>${diamondHTML(s.bases)}<strong>${s.name}</strong><span class="small">0 · 1 · 2 OUT</span></button>`).join('')}</div>`}
function situationSelect(id){const s=BASE_STATES.find(x=>x.id===id)||BASE_STATES[0];crumb.textContent=`주자 상황 > ${s.name}`;return `<section class="hero">${diamondHTML(s.bases)}<h2>${s.name}</h2><p class="lead">몇 아웃인가요?</p></section><div class="outs">${[0,1,2].map(o=>`<button class="out-btn" data-go="baseout" data-param='{"state":"${id}","outs":${o}}'>${o} OUT</button>`).join('')}</div>`}
function baseoutView(id,outs){const s=BASE_STATES.find(x=>x.id===id)||BASE_STATES[0],item=(BO[id]||BO.empty)[Number(outs)||0];const title=`${outs} OUT · ${s.name}`,key=`bo:${id}:${outs}`;crumb.textContent=`Base-Out > ${title}`;addRecent({key,title});let tags=[];if(['r3','r23'].includes(id))tags.push('OPTION');if(id==='r13')tags.push('TEAM','OPTION');return `<section class="hero">${diamondHTML(s.bases)}<div class="eyebrow">BASE-OUT</div><h1>${title}</h1></section>${tagsHTML(tags)}<div class="content-card"><h3>${item[0]}</h3><p>${item[1]}</p>${Number(outs)===2?'<div class="callout">2아웃에서는 “가장 쉬운 아웃 하나”가 가장 강력한 원칙이 된다.</div>':''}</div><div class="page-actions">${favButton(key,title)}${shareButton(title)}</div>${relatedButtons([{label:'포스/태그',route:'core-page',params:{id:'force'}},{label:'확실한 아웃',route:'core-page',params:{id:'sureout'}},{label:'내 포지션',route:'positions'}])}`}
function coreView(){crumb.textContent='HOME > CORE';return `<section class="hero"><div class="eyebrow">CORE PRINCIPLES</div><h2>경기 중 헷갈리면 여기로</h2><p class="lead">책 전체에서 반복해 사용하는 수비의 공용 언어입니다.</p></section><div class="quick-list">${CORE.map(c=>`<button class="quick-item" data-go="core-page" data-param='{"id":"${c.id}"}'><b>${c.title} <span class="tag CORE">CORE</span></b><span>${c.body}</span></button>`).join('')}</div>`}
function corePage(id){const c=CORE.find(x=>x.id===id)||CORE[0],key=`core:${c.id}`;crumb.textContent=`CORE > ${c.title}`;addRecent({key,title:c.title});return `<section class="hero"><div class="eyebrow">CORE</div><h1>${c.title}</h1></section>${tagsHTML(['CORE'])}${c.diagram?diagramHTML(c.diagram):''}<div class="content-card"><div class="callout">${c.body}</div><p>${c.detail}</p>${c.id==='contact'?'<div class="coach">“뛰면 들어가. 맞으면 다시 공이다.”</div>':''}</div><div class="page-actions">${favButton(key,c.title)}${shareButton(c.title)}</div>${relatedButtons([{label:'포지션',route:'positions'},{label:'상황',route:'situations'},{label:'플레이',route:'plays'}])}`}
function playsView(){crumb.textContent='HOME > 플레이';return `<section class="hero"><div class="eyebrow">PLAY QUICK FIND</div><h2>무슨 플레이인가요?</h2><p class="lead">경기에서 바로 맞닥뜨리는 장면을 행동 순서로 정리합니다.</p></section><div class="quick-list">${PLAY.map(p=>`<button class="quick-item" data-go="play" data-param='{"id":"${p.id}"}'><b>${p.title} ${p.tags.map(t=>`<span class="tag ${t}">${t}</span>`).join('')}</b><span>${p.sub}</span></button>`).join('')}</div>`}
function playView(id){const p=playById(id),key=`play:${p.id}`;crumb.textContent=`PLAY > ${p.title}`;addRecent({key,title:p.title});return `<section class="hero"><div class="eyebrow">PLAY</div><h1>${p.title}</h1><p class="lead">${p.sub}</p></section>${tagsHTML(p.tags)}${p.diagram?diagramHTML(p.diagram):''}<div class="content-card"><div class="steps">${p.bullets.map((b,i)=>`<div class="step"><b>${i+1}</b><div>${b}</div></div>`).join('')}</div><div class="coach">“${p.coach}”</div>${p.tags.includes('RULE')?'<div class="callout warn">RULE: 참가 리그의 로컬룰이 우선합니다. 애매하면 임의로 판정하지 말고 심판 콜을 확인하세요.</div>':''}</div><div class="page-actions">${favButton(key,p.title)}${shareButton(p.title)}</div>${relatedButtons([{label:'내 포지션',route:'positions'},{label:'Base-Out',route:'situations'},{label:'CORE',route:'core'}])}`}
function readView(){crumb.textContent='HOME > 제대로 배우기';return `<section class="hero"><div class="eyebrow">READ MODE</div><h2>처음부터 읽기</h2><p class="lead">왜 그렇게 움직이는지 이해한 뒤 경기장에서 QUICK FIND로 꺼내봅니다.</p></section><div class="chapter-list">${READ_PARTS.map((p,i)=>`<button class="chapter-card" data-go="chapter" data-param='{"id":"${p.id}"}'><span class="num">PART ${p.id}</span><b>${p.title}</b><span>${p.sub}</span></button>`).join('')}</div>`}
function chapterView(id){const p=READ_PARTS.find(x=>x.id===String(id))||READ_PARTS[0],key=`chapter:${p.id}`;crumb.textContent=`PART ${p.id} > ${p.title}`;addRecent({key,title:`PART ${p.id} ${p.title}`});return `<section class="hero"><div class="eyebrow">PART ${p.id}</div><h1>${p.title}</h1><p class="lead">${p.sub}</p></section>${p.sections.map(s=>`<section class="article-section"><h3>${s[0]}</h3><p>${s[1]}</p></section>`).join('')}${p.id==='10'?'<div class="coach">“좋은 수비수는 모든 공을 잡는 선수가 아니다. 공이 어디로 가든 팀이 그 선수를 믿을 수 있는 선수다.”</div>':''}<div class="page-actions">${favButton(key,`PART ${p.id} ${p.title}`)}${shareButton(`PART ${p.id} ${p.title}`)}</div>${relatedButtons([{label:'전체 목차',route:'read'},{label:'경기장에서 찾기',route:'game'},{label:'포지션',route:'positions'}])}`}
function favoritesView(){crumb.textContent='HOME > 저장';const favs=getFavs();return `<section class="hero"><div class="eyebrow">FAVORITES</div><h2>내가 저장한 수비</h2><p class="lead">경기 전에 자주 보는 페이지만 모아둡니다.</p></section>${favs.length?`<div class="quick-list">${favs.map(f=>`<button class="quick-item" data-route-key="${esc(f.key)}"><b>${esc(f.title)}</b><span>열기</span></button>`).join('')}</div>`:'<div class="empty">아직 저장한 페이지가 없습니다.<br>상세 페이지의 ☆ 저장 버튼을 눌러보세요.</div>'}`}
function routeKeyTo(key){const p=key.split(':');if(p[0]==='position')return routeTo('position',{id:p[1]});if(p[0]==='pt')return routeTo('position-topic',{pos:p[1],idx:Number(p[2])});if(p[0]==='core')return routeTo('core-page',{id:p[1]});if(p[0]==='play')return routeTo('play',{id:p[1]});if(p[0]==='bo')return routeTo('baseout',{state:p[1],outs:Number(p[2])});if(p[0]==='chapter')return routeTo('chapter',{id:p[1]});}
function render(){document.querySelectorAll('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.route===state.route||(b.dataset.route==='positions'&&['position','position-topic'].includes(state.route))||(b.dataset.route==='situations'&&['situation','baseout'].includes(state.route))||(b.dataset.route==='plays'&&state.route==='play')));let h='';if(state.route==='home')h=homeView();else if(state.route==='game')h=gameView();else if(state.route==='positions')h=positionsView();else if(state.route==='position')h=positionView(state.params.id);else if(state.route==='position-topic')h=positionTopic(state.params.pos,state.params.idx);else if(state.route==='situations')h=situationsView();else if(state.route==='situation')h=situationSelect(state.params.state);else if(state.route==='baseout')h=baseoutView(state.params.state,state.params.outs);else if(state.route==='core')h=coreView();else if(state.route==='core-page')h=corePage(state.params.id);else if(state.route==='plays')h=playsView();else if(state.route==='play')h=playView(state.params.id);else if(state.route==='read')h=readView();else if(state.route==='chapter')h=chapterView(state.params.id);else if(state.route==='favorites')h=favoritesView();else h=homeView();view.innerHTML=h;}
function allSearchItems(){const a=[];POSITIONS.forEach(p=>a.push({title:`${p.code} ${p.name}`,meta:'POSITION',key:`position:${p.id}`,text:[p.code,p.name,p.tag,...p.summary].join(' ')}));Object.entries(POSITION_DATA).forEach(([pid,ts])=>ts.forEach((t,i)=>a.push({title:`${positionById(pid).code} · ${t.title}`,meta:`POSITION · ${t.tags.join(' · ')}`,key:`pt:${pid}:${i}`,text:[t.title,t.teaser,...t.bullets,...(t.mistakes||[])].join(' ')})));CORE.forEach(c=>a.push({title:c.title,meta:'CORE',key:`core:${c.id}`,text:`${c.title} ${c.body} ${c.detail}`}));PLAY.forEach(p=>a.push({title:p.title,meta:p.tags.join(' · '),key:`play:${p.id}`,text:[p.title,p.sub,...p.bullets].join(' ')}));BASE_STATES.forEach(s=>[0,1,2].forEach(o=>{const it=BO[s.id][o];a.push({title:`${o} OUT · ${s.name}`,meta:'BASE-OUT',key:`bo:${s.id}:${o}`,text:`${s.name} ${o}아웃 ${it[0]} ${it[1]}`})}));READ_PARTS.forEach(p=>a.push({title:`PART ${p.id} · ${p.title}`,meta:'READ',key:`chapter:${p.id}`,text:[p.title,p.sub,...p.sections.flat()].join(' ')}));return a;}
function runSearch(q){q=q.trim().toLowerCase();const items=allSearchItems();const hits=!q?items.slice(0,15):items.filter(i=>i.text.toLowerCase().includes(q)||i.title.toLowerCase().includes(q)).slice(0,40);searchResults.innerHTML=hits.length?hits.map(h=>`<button class="search-result" data-route-key="${esc(h.key)}"><b>${esc(h.title)}</b><span>${esc(h.meta)}</span></button>`).join(''):'<div class="empty">검색 결과가 없습니다.</div>';}
view.addEventListener('click',e=>{const go=e.target.closest('[data-go]');if(go){let p={};try{p=JSON.parse(go.dataset.param||'{}')}catch{}routeTo(go.dataset.go,p);return}const f=e.target.closest('[data-fav-key]');if(f){toggleFav(f.dataset.favKey,f.dataset.favTitle);return}const rk=e.target.closest('[data-route-key]');if(rk){routeKeyTo(rk.dataset.routeKey);return}const sh=e.target.closest('[data-share-title]');if(sh){const title=sh.dataset.shareTitle;const data={title:`오태니표헤이의 사회인야구 수비의 디테일 — ${title}`,text:'사회인야구 실전 수비 모바일 매뉴얼',url:location.href};if(navigator.share)navigator.share(data).catch(()=>{});else navigator.clipboard?.writeText(location.href).then(()=>alert('링크를 복사했습니다.'));}});
document.querySelector('.bottom-nav').addEventListener('click',e=>{const b=e.target.closest('button[data-route]');if(b)routeTo(b.dataset.route)});document.querySelector('#homeBtn').addEventListener('click',()=>routeTo('home'));document.querySelector('#searchBtn').addEventListener('click',()=>{searchDialog.showModal();searchInput.value='';runSearch('');setTimeout(()=>searchInput.focus(),50)});searchInput.addEventListener('input',()=>runSearch(searchInput.value));searchResults.addEventListener('click',e=>{const b=e.target.closest('[data-route-key]');if(b){searchDialog.close();routeKeyTo(b.dataset.routeKey)}});if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));render();
